package com.example.doomeditor;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public class FsmEditorActivity extends Activity {
 private Model model;private GraphView graph;private LinearLayout inspector,root;private TextView status;private FsmRuntime runtime;private GameApi api;private Handler handler=new Handler();private long last;private final Stack<String> undo=new Stack<>(),redo=new Stack<>();private String previous="";
 int bg=0xff202938;int fg=0xffeef4ff;
 TextView label(String text,int size){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setTextColor(fg);v.setPadding(9,8,9,8);return v;}
 Button button(String t,Runnable r){Button b=new Button(this);b.setText(t);b.setTextSize(11);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
 void snapshot(){try{String now=model.json().toString();if(!now.equals(previous)){undo.push(previous);previous=now;redo.clear();}save();}catch(Exception ignored){}}
 void restore(String s){try{model=Model.parse(s);graph.model=model;graph.selected=null;api=new GameApi();runtime=new FsmRuntime(model,api);previous=s;refresh();graph.invalidate();save();}catch(Exception ex){toast(ex.getMessage());}}
 void save(){try{FileOutputStream out=openFileOutput("graph.json",MODE_PRIVATE);out.write(model.json().toString(2).getBytes("UTF-8"));out.close();}catch(Exception ignored){}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894);try{FileInputStream in=openFileInput("graph.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[2048];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);model=Model.parse(out.toString("UTF-8"));in.close();}catch(Exception e){model=new Model();Model.State idle=model.add(60,90);idle.name="Idle";Model.State chase=model.add(370,90);chase.name="Chase";Model.Edge edge=new Model.Edge(idle.id,chase.id);edge.event="SEEN";model.edges.add(edge);idle.actions.add(new Model.Action("Wait"));}api=new GameApi(){@Override public void message(String s){runOnUiThread(()->toast(s));}};runtime=new FsmRuntime(model,api);try{previous=model.json().toString();}catch(Exception ignored){}
 root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);HorizontalScrollView sc=new HorizontalScrollView(this);sc.addView(bar);root.addView(sc,new LinearLayout.LayoutParams(-1,56));bar.addView(button("+ State",()->graph.addState()));bar.addView(button("Connect",()->{if(graph.selected==null)toast("Select a source state first");else{graph.connectMode();toast("Tap destination state");}}));bar.addView(button("Undo",()->{if(!undo.empty()){redo.push(previous);restore(undo.pop());}}));bar.addView(button("Redo",()->{if(!redo.empty()){undo.push(previous);restore(redo.pop());}}));bar.addView(button("Zoom reset",()->graph.resetView()));bar.addView(button("Play",()->{runtime.start();graph.activeId=runtime.active==null?"":runtime.active.id;graph.invalidate();toast("FSM started");}));bar.addView(button("Stop",()->{runtime.stop();graph.activeId="";graph.invalidate();}));bar.addView(button("Send Event",()->input("Event name","SEEN",v->{runtime.send(v);graph.activeId=runtime.active==null?"":runtime.active.id;graph.invalidate();})));bar.addView(button("Export JSON",()->input("Copy project JSON",json(),v->{})));
 LinearLayout main=new LinearLayout(this);root.addView(main,new LinearLayout.LayoutParams(-1,0,1));graph=new GraphView(this,model);main.addView(graph,new LinearLayout.LayoutParams(0,-1,1));ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff273243);main.addView(scroll,new LinearLayout.LayoutParams(dp(300),-1));inspector=new LinearLayout(this);inspector.setOrientation(LinearLayout.VERTICAL);inspector.setPadding(8,8,8,8);scroll.addView(inspector);graph.listener=new GraphView.Listener(){public void selected(Model.State s){refresh();}public void changed(){snapshot();refresh();}};status=label("FSM Studio • Java Android Views",12);root.addView(status,new LinearLayout.LayoutParams(-1,32));refresh();last=System.currentTimeMillis();handler.post(new Runnable(){public void run(){long now=System.currentTimeMillis();if(runtime.running){runtime.update(Math.min(.1f,(now-last)/1000f));graph.activeId=runtime.active==null?"":runtime.active.id;graph.invalidate();}last=now;handler.postDelayed(this,33);}});}
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);}
 String json(){try{return model.json().toString(2);}catch(Exception e){return "{}";}}
 interface Accept {void go(String s);}
 void input(String title,String value,Accept a){EditText edit=new EditText(this);edit.setText(value);edit.setSingleLine(false);new AlertDialog.Builder(this).setTitle(title).setView(edit).setPositiveButton("OK",(d,w)->a.go(edit.getText().toString())).setNegativeButton("Cancel",null).show();}
 void section(String t){TextView v=label(t,17);v.setTextColor(0xff8dc9ff);inspector.addView(v);}
 void control(String t,Runnable r){inspector.addView(button(t,r),new LinearLayout.LayoutParams(-1,dp(44)));}
 void refresh(){if(inspector==null)return;inspector.removeAllViews();section("FSM INSPECTOR");Model.State s=graph.selected;if(s==null){inspector.addView(label("Select a state on the graph.",14));section("Project");control("Save graph",()->{save();toast("Saved");});control("Import JSON",()->input("Paste graph JSON",json(),this::restore));return;}
 section("State Settings");control("Name: "+s.name,()->input("State name",s.name,v->{s.name=v;snapshot();refresh();graph.invalidate();}));control("Description",()->input("Description",s.description,v->{s.description=v;snapshot();refresh();}));control(s.start?"★ Start State":"Set as Start State",()->{model.setStart(s);snapshot();refresh();graph.invalidate();});control("State Color",()->{s.color=s.color==0xff334b63?0xff375c47:0xff334b63;snapshot();graph.invalidate();});control("Duplicate State",()->{Model.State n=model.add(s.x+35,s.y+110);n.name=s.name+" Copy";n.description=s.description;for(Model.Action a:s.actions){Model.Action b=new Model.Action(a.type);b.argument=a.argument;b.enabled=a.enabled;n.actions.add(b);}graph.selected=n;snapshot();refresh();graph.invalidate();});control("Delete State",()->{model.remove(s);graph.selected=null;snapshot();refresh();graph.invalidate();});
 section("Actions ("+s.actions.size()+")");for(int i=0;i<s.actions.size();i++){final int index=i;Model.Action a=s.actions.get(i);control((a.enabled?"☑ ":"☐ ")+(i+1)+". "+a.type,()->actionDialog(s,index));}control("+ Add Action",()->chooseAction(s));section("Transitions");for(Model.Edge e:new ArrayList<>(model.edges))if(e.from.equals(s.id)){Model.State target=model.get(e.to);control(e.event+" → "+(target==null?"?":target.name),()->input("Transition event (empty deletes)",e.event,v->{if(v.trim().isEmpty())model.edges.remove(e);else e.event=v.trim();snapshot();refresh();graph.invalidate();}));}control("+ Connect to State",()->{graph.connectMode();toast("Tap destination node");});control("Save graph",()->{save();toast("Saved");});}
 void actionDialog(Model.State s,int index){Model.Action a=s.actions.get(index);String[] opts={"Edit argument: "+a.argument,"Toggle enabled","Move up","Move down","Delete"};new AlertDialog.Builder(this).setTitle(a.type).setItems(opts,(d,w)->{switch(w){case 0:input("Arguments (comma-separated)",a.argument,v->{a.argument=v;snapshot();refresh();});break;case 1:a.enabled=!a.enabled;break;case 2:if(index>0)Collections.swap(s.actions,index,index-1);break;case 3:if(index<s.actions.size()-1)Collections.swap(s.actions,index,index+1);break;case 4:s.actions.remove(index);break;}snapshot();refresh();}).show();}
 void chooseAction(Model.State s){EditText search=new EditText(this);search.setHint("Filter 90 actions");LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.addView(search);ListView list=new ListView(this);layout.addView(list,new LinearLayout.LayoutParams(-1,dp(350)));ArrayList<String> names=ActionRegistry.all();ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,new ArrayList<>(names));list.setAdapter(adapter);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence c,int st,int co,int a){}public void onTextChanged(CharSequence c,int st,int before,int count){adapter.getFilter().filter(c);}public void afterTextChanged(android.text.Editable e){}});AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Add Action (90)").setView(layout).setNegativeButton("Cancel",null).create();list.setOnItemClickListener((parent,v,pos,id)->{s.actions.add(new Model.Action(adapter.getItem(pos)));snapshot();refresh();dialog.dismiss();});dialog.show();}
}